-- ('Lesen Teil 2: Eine Informationstafel (wie in der Prüfung)', 'Lesen Teil 4: Anzeigen zuordnen (wie in der Prüfung)')`
-- for the 2 inserts. The ADD COLUMN is left in place (a null column is inert).

BEGIN;

ALTER TABLE public.reading_lessons ADD COLUMN IF NOT EXISTS checks jsonb;

