UPDATE public.reading_lessons SET
  title_de = 'Ein unvergessliches Erlebnis',
  title_en = 'An Unforgettable Experience',
  content_de = 'Vor drei Jahren bin ich nach Island gereist, weil ich die Nordlichter sehen wollte. Ich habe mich schon lange auf diese Reise gefreut. In Reykjavik war es sehr kalt, aber die Stadt war wunderschön.

Ein Reiseleiter hat uns erklärt, dass der Himmel klar sein muss. Ich wollte wissen, wann man die Nordlichter am besten sieht. In der zweiten Nacht sind plötzlich grüne Lichter am Himmel erschienen.

Das war sehr schön. So schön war es noch nie. Ich habe fast zwei Stunden dort gestanden und den Himmel beobachtet. Ich hatte keine Lust, viele Fotos zu machen, denn das war mir egal.

Es war teurer, als ich gedacht habe, doch es hat sich wirklich gelohnt. Ich werde diese Nacht nie vergessen. Ich würde sehr gern noch einmal nach Island fliegen.',
  content_en = 'Three years ago I traveled to Iceland because I wanted to see the Northern Lights. I have been looking forward to this trip for a long time. In Reykjavik it was very cold, but the city was beautiful.

A tour guide explained to us that the sky has to be clear. I wanted to know when you can best see the Northern Lights. On the second night, green lights suddenly appeared in the sky.

That was very beautiful. It had never been so beautiful. I stood there for almost two hours and watched the sky. I didn''t feel like taking many photos, because that didn''t matter to me.

It was more expensive than I had thought, but it was really worth it. I will never forget that night. I would love to fly to Iceland again.',
  key_vocabulary = '[{"de":"der Reiseleiter, -","en":"tour guide"},{"de":"reisen","en":"to travel"},{"de":"sich freuen (auf + Akk.)","en":"to look forward (to)"},{"de":"der Himmel","en":"sky"},{"de":"erklären","en":"to explain"},{"de":"plötzlich","en":"suddenly"},{"de":"erscheinen","en":"to appear"},{"de":"beobachten","en":"to observe, to watch"},{"de":"sich lohnen","en":"to be worth it"},{"de":"vergessen","en":"to forget"},{"de":"teuer","en":"expensive"},{"de":"die Nacht, ¨-e","en":"night"}]'::jsonb,
  questions = '[{"question_de":"Warum ist die Person nach Island gereist?","question_en":"Why did the person travel to Iceland?","answer_de":"Weil sie die Nordlichter sehen wollte.","answer_en":"Because she wanted to see the Northern Lights."},{"question_de":"Wie war das Wetter in Reykjavik?","question_en":"What was the weather like in Reykjavik?","answer_de":"Es war sehr kalt, aber die Stadt war wunderschön.","answer_en":"It was very cold, but the city was beautiful."},{"question_de":"Was hat der Reiseleiter erklärt?","question_en":"What did the tour guide explain?","answer_de":"Dass der Himmel klar sein muss.","answer_en":"That the sky has to be clear."},{"question_de":"Wann sind die grünen Lichter erschienen?","question_en":"When did the green lights appear?","answer_de":"In der zweiten Nacht sind sie plötzlich am Himmel erschienen.","answer_en":"On the second night they suddenly appeared in the sky."},{"question_de":"Möchte die Person noch einmal nach Island fliegen?","question_en":"Would the person like to fly to Iceland again?","answer_de":"Ja, sie würde sehr gern noch einmal fliegen.","answer_en":"Yes, she would love to fly there again."}]'::jsonb,
  checks = '[{"type":"rf","answer":"richtig","statement_de":"Die Person wollte in Island die Nordlichter sehen.","statement_en":"The person wanted to see the Northern Lights in Iceland.","explanation_de":"Im Text steht: Vor drei Jahren bin ich nach Island gereist, weil ich die Nordlichter sehen wollte."},{"type":"rf","answer":"falsch","statement_de":"In Reykjavik war es warm.","statement_en":"It was warm in Reykjavik.","explanation_de":"Im Text steht: In Reykjavik war es sehr kalt."},{"type":"rf","answer":"richtig","statement_de":"Ein Reiseleiter hat der Gruppe etwas über den Himmel erklärt.","statement_en":"A tour guide explained something about the sky to the group.","explanation_de":"Im Text steht: Ein Reiseleiter hat uns erklärt, dass der Himmel klar sein muss."},{"type":"rf","answer":"falsch","statement_de":"Die Lichter sind schon in der ersten Nacht erschienen.","statement_en":"The lights already appeared on the first night.","explanation_de":"Im Text steht: In der zweiten Nacht sind plötzlich Lichter am Himmel erschienen."},{"type":"rf","answer":"falsch","statement_de":"Die Reise war günstiger, als die Person gedacht hat.","statement_en":"The trip was cheaper than the person had expected.","explanation_de":"Im Text steht: Es war teurer, als ich gedacht habe."},{"type":"choice","answer":"b","options":["a","b","c"],"statement_de":"Wie lange hat die Person den Himmel beobachtet? a) eine Stunde b) fast zwei Stunden c) drei Stunden","statement_en":"How long did the person watch the sky? a) one hour b) almost two hours c) three hours","explanation_de":"Im Text steht: Ich habe fast zwei Stunden dort gestanden und den Himmel beobachtet."}]'::jsonb,
  word_count = 128,
  estimated_reading_time = 2
WHERE id = '97eb408c-551a-45ce-b1e3-c51c41668f59'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Meine Pläne für die Zukunft',
  title_en = 'My Plans for the Future',
  content_de = 'Ich denke oft über meine Zukunft nach. Im Moment arbeite ich als Marketingmanagerin in einer Firma. Die Arbeit gefällt mir, aber ich habe größere Träume.

Ich hoffe, dass ich in drei Jahren eine höhere Position habe. Nächstes Jahr möchte ich einen Kurs in Betriebswirtschaft machen. Der Kurs wird zwei Jahre dauern, und ich werde am Wochenende lernen.

Mein Partner und ich werden im Sommer heiraten. Wir haben vor, in ein paar Jahren Kinder zu bekommen. Danach werden wir sicher ein größeres Haus brauchen.

Ich interessiere mich auch für neue Sprachen. Ich weiß noch nicht, welche Sprache ich zuerst lerne. Vielleicht wähle ich Spanisch, weil meine Firma Kunden in Spanien hat.

Ich bin optimistisch, wenn ich an die Zukunft denke. Ich würde gern viel erreichen, aber ich weiß: Nicht alles läuft nach Plan.',
  content_en = 'I often think about my future. At the moment I work as a marketing manager at a company. I like the work, but I have bigger dreams.

I hope that I will have a higher position in three years. Next year I want to do a course in business administration. The course will last two years, and I will study on weekends.

My partner and I are getting married in the summer. We plan to have children in a few years. After that we will surely need a bigger house.

I am also interested in new languages. I don''t know yet which language I will learn first. Maybe I will choose Spanish, because my company has customers in Spain.

I am optimistic when I think about the future. I would love to achieve a lot, but I know: not everything goes according to plan.',
  key_vocabulary = '[{"de":"die Zukunft","en":"future"},{"de":"der Traum, ¨-e","en":"dream"},{"de":"die Position, -en","en":"position"},{"de":"die Betriebswirtschaft","en":"business administration"},{"de":"dauern","en":"to last"},{"de":"heiraten","en":"to marry"},{"de":"vorhaben","en":"to plan, to intend"},{"de":"sich interessieren (für + Akk.)","en":"to be interested (in)"},{"de":"wählen","en":"to choose"},{"de":"optimistisch","en":"optimistic"},{"de":"erreichen","en":"to achieve"},{"de":"der Plan, ¨-e","en":"plan"}]'::jsonb,
  questions = '[{"question_de":"Was ist ihr Beruf?","question_en":"What is the person''s job?","answer_de":"Sie arbeitet als Marketingmanagerin.","answer_en":"She works as a marketing manager."},{"question_de":"Was möchte die Person nächstes Jahr machen?","question_en":"What does the person want to do next year?","answer_de":"Sie möchte einen Kurs in Betriebswirtschaft machen.","answer_en":"She wants to do a course in business administration."},{"question_de":"Wie lange wird der Kurs dauern?","question_en":"How long will the course last?","answer_de":"Der Kurs wird zwei Jahre dauern.","answer_en":"The course will last two years."},{"question_de":"Was haben die Person und ihr Partner vor?","question_en":"What do the person and her partner plan to do?","answer_de":"Sie haben vor, in ein paar Jahren Kinder zu bekommen.","answer_en":"They plan to have children in a few years."},{"question_de":"Welche Sprache möchte die Person vielleicht lernen?","question_en":"Which language might the person learn?","answer_de":"Vielleicht wählt sie Spanisch.","answer_en":"Maybe she will choose Spanish."}]'::jsonb,
  checks = '[{"type":"rf","answer":"richtig","statement_de":"Die Person arbeitet als Marketingmanagerin.","statement_en":"The person works as a marketing manager.","explanation_de":"Im Text steht: Im Moment arbeite ich als Marketingmanagerin in einer Firma."},{"type":"rf","answer":"falsch","statement_de":"Die Person möchte in drei Jahren eine niedrigere Position haben.","statement_en":"The person wants a lower position in three years.","explanation_de":"Im Text steht: Ich hoffe, dass ich in drei Jahren eine höhere Position habe."},{"type":"rf","answer":"richtig","statement_de":"Der Kurs dauert zwei Jahre.","statement_en":"The course lasts two years.","explanation_de":"Im Text steht: Der Kurs wird zwei Jahre dauern."},{"type":"rf","answer":"falsch","statement_de":"Die Person und ihr Partner heiraten im Winter.","statement_en":"The person and her partner are getting married in winter.","explanation_de":"Im Text steht: Mein Partner und ich werden im Sommer heiraten."},{"type":"rf","answer":"falsch","statement_de":"Die Person interessiert sich nicht für Sprachen.","statement_en":"The person is not interested in languages.","explanation_de":"Im Text steht: Ich interessiere mich auch für Sprachen."},{"type":"choice","answer":"b","options":["a","b","c"],"statement_de":"Was werden die Person und ihr Partner brauchen, wenn sie Kinder haben? a) ein größeres Auto b) ein größeres Haus c) eine größere Wohnung","statement_en":"What will the person and her partner need once they have children? a) a bigger car b) a bigger house c) a bigger apartment","explanation_de":"Im Text steht: Danach werden wir sicher ein größeres Haus brauchen."}]'::jsonb,
  word_count = 132,
  estimated_reading_time = 2
WHERE id = '93659e93-627e-45b1-8a67-3102b009e03e'
