UPDATE public.reading_lessons SET
  title_de = 'Wahre Freundschaft',
  title_en = 'True Friendship',
  content_de = 'Meine beste Freundin heißt Sarah. Wir haben uns vor fünfzehn Jahren in der Schule kennengelernt. Am Anfang mochten wir uns nicht besonders.

Aber wir haben gemerkt, dass wir viele gemeinsame Interessen haben. Seit dieser Zeit sind wir sehr gute Freundinnen. Ich kann Sarah alles erzählen, und sie hört mir immer zu.

Wenn ich Probleme habe, erzähle ich es zuerst ihr. Wir haben manchmal verschiedene Meinungen, aber wir respektieren uns immer. Ich weiß nicht, was ich ohne sie mache.

Jetzt wohnt Sarah in einer anderen Stadt. Wir telefonieren jede Woche und schreiben uns oft Nachrichten. Ich freue mich immer sehr auf ihre Anrufe.

Ich treffe mich auch oft mit Freunden aus der Universität. Wir gehen zusammen essen oder feiern Geburtstage. Das macht mir immer viel Spaß.

Ich habe gelernt: Es ist wichtig, wenige echte Freunde zu haben. Ein wahrer Freund bleibt auch in schwierigen Zeiten da.',
  content_en = 'My best friend''s name is Sarah. We met fifteen years ago at school. At first we didn''t like each other very much.

But we noticed that we have many common interests. Since that time we have been very good friends. I can tell Sarah everything, and she always listens to me.

When I have problems, I tell her first. We sometimes have different opinions, but we always respect each other. I don''t know what I do without her.

Now Sarah lives in another city. We talk on the phone every week and often write each other messages. I always look forward to her calls very much.

I also often meet up with friends from university. We go out to eat together or celebrate birthdays. That is always a lot of fun for me.

I have learned: it is important to have a few real friends. A true friend is there for you even in difficult times.',
  key_vocabulary = '[{"de":"die Freundin, -nen","en":"friend (female)"},{"de":"kennenlernen","en":"to get to know"},{"de":"gemeinsam","en":"common, shared"},{"de":"das Interesse, -n","en":"interest"},{"de":"erzählen","en":"to tell"},{"de":"zuhören (+ Dat.)","en":"to listen (to someone)"},{"de":"die Meinung, -en","en":"opinion"},{"de":"respektieren","en":"to respect"},{"de":"der Anruf, -e","en":"phone call"},{"de":"sich treffen (mit + Dat.)","en":"to meet (with)"},{"de":"feiern","en":"to celebrate"},{"de":"echt","en":"real, genuine"},{"de":"schwierig","en":"difficult"}]'::jsonb,
  questions = '[{"question_de":"Wie heißt ihre beste Freundin?","question_en":"What is the person''s best friend called?","answer_de":"Sie heißt Sarah.","answer_en":"Her name is Sarah."},{"question_de":"Wann haben sich die beiden kennengelernt?","question_en":"When did the two of them meet?","answer_de":"Sie haben sich vor fünfzehn Jahren in der Schule kennengelernt.","answer_en":"They met fifteen years ago at school."},{"question_de":"Was macht die Person, wenn sie Probleme hat?","question_en":"What does the person do when she has problems?","answer_de":"Sie erzählt es zuerst Sarah.","answer_en":"She tells Sarah first."},{"question_de":"Wie oft telefonieren die beiden Freundinnen?","question_en":"How often do the two friends talk on the phone?","answer_de":"Sie telefonieren jede Woche.","answer_en":"They talk on the phone every week."},{"question_de":"Was hat die Person über Freundschaft gelernt?","question_en":"What has the person learned about friendship?","answer_de":"Dass es wichtig ist, wenige echte Freunde zu haben.","answer_en":"That it is important to have a few real friends."}]'::jsonb,
  checks = '[{"type":"rf","answer":"richtig","statement_de":"Die Person hat Sarah in der Schule kennengelernt.","statement_en":"The person met Sarah at school.","explanation_de":"Im Text steht: Wir haben uns vor fünfzehn Jahren in der Schule kennengelernt."},{"type":"rf","answer":"falsch","statement_de":"Sarah und die Person mochten sich am Anfang sofort sehr gern.","statement_en":"Sarah and the person liked each other very much right from the start.","explanation_de":"Im Text steht: Am Anfang mochten wir uns nicht besonders."},{"type":"rf","answer":"richtig","statement_de":"Sarah wohnt jetzt in einer anderen Stadt.","statement_en":"Sarah now lives in another city.","explanation_de":"Im Text steht: Jetzt wohnt Sarah in einer anderen Stadt."},{"type":"rf","answer":"falsch","statement_de":"Die beiden Freundinnen telefonieren nur einmal im Monat.","statement_en":"The two friends only talk on the phone once a month.","explanation_de":"Im Text steht: Wir telefonieren jede Woche."},{"type":"rf","answer":"richtig","statement_de":"Die Person trifft sich auch mit Freunden aus der Universität.","statement_en":"The person also meets up with friends from university.","explanation_de":"Im Text steht: Ich treffe mich auch oft mit Freunden aus der Universität."},{"type":"choice","answer":"a","options":["a","b","c"],"statement_de":"Was macht die Person mit Freunden aus der Universität? a) Sie gehen essen oder feiern Geburtstage. b) Sie gehen ins Kino. c) Sie spielen Fußball.","statement_en":"What does the person do with friends from university? a) They go out to eat or celebrate birthdays. b) They go to the cinema. c) They play football.","explanation_de":"Im Text steht: Wir gehen zusammen essen oder feiern Geburtstage."}]'::jsonb,
  word_count = 145,
  estimated_reading_time = 2
WHERE id = '95de28dd-c68e-4b5a-8bcc-446aa817b0fb'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
