UPDATE public.reading_lessons SET
  title_de = 'Wohnungssuche in Deutschland',
  title_en = 'Apartment Hunting in Germany',
  content_de = 'Es kann schwierig sein, eine Wohnung in Deutschland zu finden. In großen Städten wie München oder Berlin sind die Mieten hoch. Ich habe letztes Jahr eine neue Wohnung gesucht.

Zuerst habe ich im Internet gesucht. Ich habe jeden Tag neue Anzeigen angeschaut und viele E-Mails geschrieben. Leider haben die meisten Vermieter nicht geantwortet.

Nach zwei Wochen hatte ich endlich einen Besichtigungstermin. Die erste Wohnung war klein und dunkel. Das hat mir nicht gefallen. Bei der zweiten Wohnung waren zwanzig andere Interessenten da!

Für eine Wohnung braucht man viele Dokumente. Die Vermieter wollen meistens eine Schufa-Auskunft sehen. Ich musste auch einen Gehaltsnachweis vorbereiten.

Nach sechs Wochen habe ich endlich meine Traumwohnung gefunden. Sie hat drei Zimmer und ist hell und ruhig. Ich musste einen Mietvertrag unterschreiben und eine Kaution bezahlen.

Mein Tipp: Seid geduldig und gebt nicht auf! Die Suche dauert oft viele Wochen. Bereitet vorher alle Dokumente vor.',
  content_en = 'It can be difficult to find an apartment in Germany. In big cities like Munich or Berlin, rents are high. Last year I looked for a new apartment.

First I searched on the internet. I looked at new listings every day and wrote many emails. Unfortunately most landlords did not answer.

After two weeks I finally had a viewing appointment. The first apartment was small and dark, and I didn''t like that. At the second apartment there were twenty other interested people!

You need many documents for an apartment. Landlords usually want to see a credit report. I also had to prepare proof of income.

After six weeks I finally found my dream apartment. It has three rooms and is bright and quiet. I had to sign a rental contract and pay a deposit.

My tip: be patient and don''t give up! The search often takes many weeks. Prepare all your documents beforehand.',
  key_vocabulary = '[{"de":"die Miete, -n","en":"rent"},{"de":"die Anzeige, -n","en":"advertisement, listing"},{"de":"der Vermieter, -","en":"landlord"},{"de":"antworten","en":"to answer"},{"de":"der Besichtigungstermin, -e","en":"viewing appointment"},{"de":"das Dokument, -e","en":"document"},{"de":"der Gehaltsnachweis, -e","en":"proof of income"},{"de":"die Traumwohnung, -en","en":"dream apartment"},{"de":"der Mietvertrag, ¨-e","en":"rental contract"},{"de":"unterschreiben","en":"to sign"},{"de":"die Kaution, -en","en":"deposit"},{"de":"geduldig","en":"patient"}]'::jsonb,
  questions = '[{"question_de":"Warum kann es schwierig sein, in Deutschland eine Wohnung zu finden?","question_en":"Why can it be difficult to find an apartment in Germany?","answer_de":"Weil die Mieten in den großen Städten hoch sind.","answer_en":"Because rents are high in the big cities."},{"question_de":"Wo hat die Person zuerst nach einer Wohnung gesucht?","question_en":"Where did the person first look for an apartment?","answer_de":"Sie hat zuerst im Internet gesucht.","answer_en":"She first searched on the internet."},{"question_de":"Wie viele Interessenten waren bei der zweiten Besichtigung da?","question_en":"How many interested people were at the second viewing?","answer_de":"Zwanzig andere Interessenten waren da.","answer_en":"Twenty other interested people were there."},{"question_de":"Welches Dokument wollen die Vermieter meistens sehen?","question_en":"Which document do landlords usually want to see?","answer_de":"Sie wollen meistens eine Schufa-Auskunft sehen.","answer_en":"They usually want to see a credit report."},{"question_de":"Was musste die Person für die neue Wohnung machen?","question_en":"What did the person have to do for the new apartment?","answer_de":"Sie musste einen Mietvertrag unterschreiben und eine Kaution bezahlen.","answer_en":"She had to sign a rental contract and pay a deposit."}]'::jsonb,
  checks = '[{"type":"rf","answer":"richtig","statement_de":"In den großen Städten wie München sind die Mieten hoch.","statement_en":"In the big cities like Munich, rents are high.","explanation_de":"Im Text steht: In den großen Städten wie München oder Berlin sind die Mieten hoch."},{"type":"rf","answer":"falsch","statement_de":"Die Person hat zuerst in der Zeitung gesucht.","statement_en":"The person first looked in the newspaper.","explanation_de":"Im Text steht: Zuerst habe ich im Internet gesucht."},{"type":"rf","answer":"falsch","statement_de":"Die meisten Vermieter haben schnell geantwortet.","statement_en":"Most landlords answered quickly.","explanation_de":"Im Text steht: Leider haben die meisten Vermieter nicht geantwortet."},{"type":"rf","answer":"richtig","statement_de":"Bei der zweiten Wohnung waren zwanzig andere Interessenten da.","statement_en":"At the second apartment there were twenty other interested people.","explanation_de":"Im Text steht: Bei der zweiten Wohnung waren zwanzig andere Interessenten da!"},{"type":"rf","answer":"richtig","statement_de":"Die Person hat nach sechs Wochen ihre Traumwohnung gefunden.","statement_en":"The person found her dream apartment after six weeks.","explanation_de":"Im Text steht: Nach sechs Wochen habe ich endlich meine Traumwohnung gefunden."},{"type":"choice","answer":"b","options":["a","b","c"],"statement_de":"Wie lange hat die Wohnungssuche insgesamt gedauert? a) zwei Wochen b) sechs Wochen c) zehn Wochen","statement_en":"How long did the apartment search take in total? a) two weeks b) six weeks c) ten weeks","explanation_de":"Im Text steht: Nach sechs Wochen habe ich endlich meine Traumwohnung gefunden."}]'::jsonb,
  word_count = 148,
  estimated_reading_time = 3
WHERE id = 'bc75f43c-087b-4012-a2a6-bb3726005d28'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Medien und Nachrichten',
  title_en = 'Media and News',
  content_de = 'Wir leben in einer Zeit mit sehr vielen Informationen. Nachrichten kommen aus dem Fernsehen, dem Radio und dem Internet. Ich erzähle euch, wie ich Nachrichten lese.

Früher haben meine Eltern jeden Morgen die Zeitung gelesen. Heute lesen viele Menschen keine Zeitung mehr auf Papier. Sie lesen ihre Nachrichten kostenlos im Internet.

Ich selbst lese Nachrichten meistens online. Ich interessiere mich besonders für internationale Nachrichten. Ich habe mehrere News-Apps auf meinem Handy.

Abends schaue ich manchmal die Tagesschau im Fernsehen. Sie läuft jeden Abend um 20 Uhr und dauert 15 Minuten. Mir gefällt, dass sie neutral berichtet.

In sozialen Medien gibt es leider auch viele Falschnachrichten. Deshalb ist es wichtig, kritisch zu denken. Ich möchte wissen, wer eine Nachricht geschrieben hat.

Manchmal machen mich negative Nachrichten müde. Dann nehme ich mir eine Pause vom Handy. Ich würde gern öfter positive Nachrichten lesen.',
  content_en = 'We live in a time with a lot of information. News comes from television, radio, and the internet. I will tell you how I read the news.

In the past, my parents read the newspaper every morning. Today many people no longer read the newspaper on paper. They read their news for free on the internet.

I myself mostly read news online. I am especially interested in international news. I have several news apps on my phone.

In the evening I sometimes watch the Tagesschau on TV. It airs every evening at 8 p.m. and lasts 15 minutes. I like that it reports neutrally.

Unfortunately there is also a lot of fake news on social media. That''s why it''s important to think critically. I want to know who wrote a piece of news.

Sometimes negative news makes me tired. Then I take a break from my phone. I would like to read more positive news.',
  key_vocabulary = '[{"de":"die Information, -en","en":"information"},{"de":"die Nachricht, -en","en":"news"},{"de":"die App, -s","en":"app"},{"de":"kostenlos","en":"free of charge"},{"de":"sich interessieren (für + Akk.)","en":"to be interested in"},{"de":"die Tagesschau","en":"German TV news programme"},{"de":"berichten","en":"to report"},{"de":"neutral","en":"neutral"},{"de":"die Falschnachricht, -en","en":"fake news"},{"de":"kritisch","en":"critical"},{"de":"die Pause, -n","en":"break"},{"de":"positiv","en":"positive"}]'::jsonb,
  questions = '[{"question_de":"Woher kommen die Nachrichten heute?","question_en":"Where does the news come from today?","answer_de":"Sie kommen aus dem Fernsehen, dem Radio und dem Internet.","answer_en":"It comes from television, radio and the internet."},{"question_de":"Was haben ihre Eltern früher jeden Morgen gemacht?","question_en":"What did the person''s parents do every morning in the past?","answer_de":"Sie haben jeden Morgen die Zeitung gelesen.","answer_en":"They read the newspaper every morning."},{"question_de":"Wie liest die Person heute meistens Nachrichten?","question_en":"How does the person mostly read news today?","answer_de":"Sie liest sie meistens online, mit News-Apps.","answer_en":"She mostly reads it online, with news apps."},{"question_de":"Wann läuft die Tagesschau?","question_en":"When does the Tagesschau air?","answer_de":"Sie läuft jeden Abend um 20 Uhr.","answer_en":"It airs every evening at 8 p.m."},{"question_de":"Was macht die Person, wenn die negativen Nachrichten sie müde machen?","question_en":"What does the person do when negative news makes her tired?","answer_de":"Sie nimmt sich eine Pause vom Handy.","answer_en":"She takes a break from her phone."}]'::jsonb,
  checks = '[{"type":"rf","answer":"richtig","statement_de":"Ihre Eltern haben früher jeden Morgen die Zeitung gelesen.","statement_en":"The person''s parents used to read the newspaper every morning.","explanation_de":"Im Text steht: Früher haben meine Eltern jeden Morgen die Zeitung gelesen."},{"type":"rf","answer":"falsch","statement_de":"Die Person liest ihre Nachrichten meistens auf Papier.","statement_en":"The person mostly reads her news on paper.","explanation_de":"Im Text steht: Ich selbst lese Nachrichten meistens online."},{"type":"rf","answer":"richtig","statement_de":"Die Tagesschau dauert 15 Minuten.","statement_en":"The Tagesschau lasts 15 minutes.","explanation_de":"Im Text steht: Sie läuft jeden Abend um 20 Uhr und dauert 15 Minuten."},{"type":"rf","answer":"falsch","statement_de":"In den sozialen Medien gibt es keine Falschnachrichten.","statement_en":"There is no fake news on social media.","explanation_de":"Im Text steht: In den sozialen Medien gibt es leider auch viele Falschnachrichten."},{"type":"rf","answer":"richtig","statement_de":"Die negativen Nachrichten machen die Person manchmal müde.","statement_en":"Negative news sometimes makes the person tired.","explanation_de":"Im Text steht: Manchmal machen mich die negativen Nachrichten müde."},{"type":"choice","answer":"b","options":["a","b","c"],"statement_de":"Wie lange dauert die Tagesschau? a) 10 Minuten b) 15 Minuten c) 20 Minuten","statement_en":"How long does the Tagesschau last? a) 10 minutes b) 15 minutes c) 20 minutes","explanation_de":"Im Text steht: Sie läuft jeden Abend um 20 Uhr und dauert 15 Minuten."}]'::jsonb,
  word_count = 141,
  estimated_reading_time = 2
WHERE id = '21669a68-c401-4d94-bd83-a0ad5a41e1a4'
