UPDATE public.reading_lessons SET
  title_de = 'Deutsche Kultur und Traditionen',
  title_en = 'German Culture and Traditions',
  content_de = 'Deutschland hat eine reiche Kultur mit vielen Traditionen. Einige Traditionen finde ich besonders interessant.

Eine bekannte Tradition ist Weihnachten. Die Deutschen feiern es am 24. Dezember, nicht erst am 25. Die Familie kommt zusammen und tauscht Geschenke aus.

Das Oktoberfest in München ist weltberühmt. Es dauert etwa zwei Wochen im September und Oktober. Ich würde gern einmal selbst dort mitfeiern.

Karneval feiert man vor allem im Rheinland, besonders in Köln. Die Menschen verkleiden sich und feiern auf der Straße. Der Höhepunkt ist ein großer Umzug mit bunten Wagen.

Deutsche sind auch für ihre Pünktlichkeit bekannt. Zu spät zu kommen gilt hier als unhöflich. Ich habe mich oft gefragt, warum Pünktlichkeit hier so wichtig ist.

Außerdem ist Recycling in Deutschland sehr wichtig. Die Menschen trennen ihren Müll sorgfältig. Wenn ihr nach Deutschland kommt, werdet ihr das schnell merken.',
  content_en = 'Germany has a rich culture with many traditions. I find some traditions especially interesting.

One well-known tradition is Christmas. Germans celebrate it on December 24th, not until the 25th. The family comes together and exchanges presents.

The Oktoberfest in Munich is world-famous. It lasts about two weeks in September and October. I would love to join in there myself sometime.

Carnival is celebrated mainly in the Rhineland, especially in Cologne. People dress up and celebrate in the streets. The highlight is a big parade with colorful floats.

Germans are also known for their punctuality. Being late is considered impolite here. I have often wondered why punctuality is so important here.

Recycling is also very important in Germany. People carefully sort their trash. If you come to Germany, you will notice that quickly.',
  key_vocabulary = '[{"de":"die Tradition, -en","en":"tradition"},{"de":"feiern","en":"to celebrate"},{"de":"das Geschenk, -e","en":"present"},{"de":"weltberühmt","en":"world-famous"},{"de":"dauern","en":"to last"},{"de":"sich verkleiden","en":"to dress up, disguise oneself"},{"de":"der Höhepunkt, -e","en":"highlight"},{"de":"der Umzug, ¨-e","en":"parade"},{"de":"pünktlich","en":"punctual"},{"de":"unhöflich","en":"impolite"},{"de":"der Müll","en":"waste, rubbish"},{"de":"trennen","en":"to separate"}]'::jsonb,
  questions = '[{"question_de":"Wann feiern die Deutschen Weihnachten?","question_en":"When do Germans celebrate Christmas?","answer_de":"Sie feiern es am 24. Dezember.","answer_en":"They celebrate it on December 24th."},{"question_de":"Wie lange dauert das Oktoberfest?","question_en":"How long does the Oktoberfest last?","answer_de":"Es dauert etwa zwei Wochen.","answer_en":"It lasts about two weeks."},{"question_de":"Wo feiert man Karneval besonders?","question_en":"Where is Carnival celebrated especially?","answer_de":"Man feiert ihn besonders im Rheinland, in Köln.","answer_en":"It is celebrated especially in the Rhineland, in Cologne."},{"question_de":"Wofür sind die Deutschen bekannt?","question_en":"What are Germans known for?","answer_de":"Sie sind für ihre Pünktlichkeit bekannt.","answer_en":"They are known for their punctuality."},{"question_de":"Was machen die Menschen in Deutschland mit ihrem Müll?","question_en":"What do people in Germany do with their trash?","answer_de":"Sie trennen ihn sorgfältig.","answer_en":"They carefully separate it."}]'::jsonb,
  checks = '[{"type":"rf","answer":"falsch","statement_de":"Die Deutschen feiern Weihnachten am 25. Dezember.","statement_en":"Germans celebrate Christmas on December 25th.","explanation_de":"Im Text steht: Die Deutschen feiern es am 24. Dezember, nicht erst am 25."},{"type":"rf","answer":"richtig","statement_de":"Das Oktoberfest dauert etwa zwei Wochen.","statement_en":"The Oktoberfest lasts about two weeks.","explanation_de":"Im Text steht: Es dauert etwa zwei Wochen im September und Oktober."},{"type":"rf","answer":"richtig","statement_de":"Karneval feiert man besonders im Rheinland.","statement_en":"Carnival is celebrated especially in the Rhineland.","explanation_de":"Im Text steht: Karneval feiert man vor allem im Rheinland, besonders in Köln."},{"type":"rf","answer":"falsch","statement_de":"In Deutschland ist es höflich, wenn man zu spät kommt.","statement_en":"In Germany it is polite to arrive late.","explanation_de":"Im Text steht: Zu spät zu kommen gilt hier als unhöflich."},{"type":"rf","answer":"falsch","statement_de":"Die Menschen in Deutschland trennen ihren Müll nicht.","statement_en":"People in Germany do not separate their trash.","explanation_de":"Im Text steht: Die Menschen trennen ihren Müll sorgfältig."},{"type":"choice","answer":"b","options":["a","b","c"],"statement_de":"Was gilt in Deutschland als unhöflich? a) zu früh kommen b) zu spät kommen c) ein Geschenk mitbringen","statement_en":"What is considered impolite in Germany? a) arriving too early b) arriving too late c) bringing a present","explanation_de":"Im Text steht: Zu spät zu kommen gilt hier als unhöflich."}]'::jsonb,
  word_count = 137,
  estimated_reading_time = 2
WHERE id = '7f463279-29de-4537-ae9b-bfc210759168'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Feste und Feiertage in Deutschland',
  title_en = 'Festivals and Holidays in Germany',
  content_de = 'Deutschland feiert gern, und jede Jahreszeit hat ihre Höhepunkte. Wenn man die deutsche Kultur verstehen möchte, muss man die wichtigsten Feste kennen.

Im Winter beginnt die Adventszeit. Ab Ende November öffnen überall die Weihnachtsmärkte. Der Nürnberger Christkindlesmarkt ist sehr bekannt und sehr alt. Er existiert schon seit vielen Jahrhunderten.

Auf dem Markt trinkt man Glühwein und isst süße Mandeln. Weihnachten selbst feiert man am 24. Dezember mit der ganzen Familie.

Im Februar beginnt der Karneval. Am stärksten feiert man ihn im Rheinland, besonders in Köln. Am Rosenmontag ziehen große Umzüge durch die Stadt, und die Menschen rufen „Kamelle!“.

Der wichtigste politische Feiertag ist der 3. Oktober. An diesem Tag feiert man die deutsche Einheit von 1990. Dieser Feiertag gilt im ganzen Land.

Wenn Sie in Deutschland leben, werden Sie diese Feste sicher gern miterleben. Probieren Sie am besten alles einmal aus!',
  content_en = 'Germany likes to celebrate, and every season has its highlights. If you want to understand German culture, you have to know the most important festivals.

Winter begins the Advent season. From late November, Christmas markets open everywhere. The Nuremberg Christkindlesmarkt is very well known and very old. It has existed for many centuries.

At the market people drink Glühwein and eat sweet almonds. Christmas itself is celebrated on December 24th with the whole family.

In February, Carnival begins. It is celebrated most strongly in the Rhineland, especially in Cologne. On Rosenmontag, big parades move through the city, and people shout "Kamelle!" (sweets!)

The most important political holiday is October 3rd. On this day Germany celebrates its reunification from 1990. This holiday applies throughout the whole country.

If you live in Germany, you will surely enjoy experiencing these festivals. Best of all, try everything once!',
  key_vocabulary = '[{"de":"die Jahreszeit, -en","en":"season"},{"de":"die Adventszeit","en":"Advent season"},{"de":"der Weihnachtsmarkt, ¨-e","en":"Christmas market"},{"de":"der Glühwein","en":"mulled wine"},{"de":"die Mandel, -n","en":"almond"},{"de":"der Umzug, ¨-e","en":"parade"},{"de":"rufen","en":"to shout"},{"de":"der Feiertag, -e","en":"public holiday"},{"de":"die Einheit","en":"unity"},{"de":"gelten (als)","en":"to apply, to count (as)"},{"de":"miterleben","en":"to experience, to witness"}]'::jsonb,
  questions = '[{"question_de":"Wann öffnen die Weihnachtsmärkte?","question_en":"When do the Christmas markets open?","answer_de":"Sie öffnen ab Ende November.","answer_en":"They open from late November."},{"question_de":"Was trinkt und isst man auf dem Weihnachtsmarkt?","question_en":"What do people drink and eat at the Christmas market?","answer_de":"Man trinkt Glühwein und isst die süßen Mandeln.","answer_en":"People drink Glühwein and eat sweet almonds."},{"question_de":"Wo feiert man Karneval am stärksten?","question_en":"Where is Carnival celebrated most strongly?","answer_de":"Man feiert ihn am stärksten im Rheinland, besonders in Köln.","answer_en":"It is celebrated most strongly in the Rhineland, especially in Cologne."},{"question_de":"Welches Datum ist der wichtigste politische Feiertag?","question_en":"What date is the most important political holiday?","answer_de":"Es ist der 3. Oktober.","answer_en":"It is October 3rd."},{"question_de":"Was feiert man am 3. Oktober?","question_en":"What is celebrated on October 3rd?","answer_de":"Man feiert die deutsche Einheit von 1990.","answer_en":"German reunification from 1990 is celebrated."}]'::jsonb,
  checks = '[{"type":"rf","answer":"richtig","statement_de":"Der Nürnberger Christkindlesmarkt ist sehr alt.","statement_en":"The Nuremberg Christkindlesmarkt is very old.","explanation_de":"Im Text steht: Der Nürnberger Christkindlesmarkt ist sehr bekannt und sehr alt."},{"type":"rf","answer":"falsch","statement_de":"Weihnachten feiert man in Deutschland am 25. Dezember.","statement_en":"Christmas is celebrated in Germany on December 25th.","explanation_de":"Im Text steht: Weihnachten selbst feiert man am 24. Dezember."},{"type":"rf","answer":"richtig","statement_de":"Am Rosenmontag ziehen die großen Umzüge durch die Stadt.","statement_en":"On Rosenmontag, big parades move through the city.","explanation_de":"Im Text steht: Am Rosenmontag ziehen die großen Umzüge durch die Stadt."},{"type":"rf","answer":"falsch","statement_de":"Der 3. Oktober gilt nur in einem Bundesland.","statement_en":"October 3rd applies only in one federal state.","explanation_de":"Im Text steht: Dieser Feiertag gilt im ganzen Land."},{"type":"rf","answer":"falsch","statement_de":"Am 3. Oktober feiert man den Beginn vom Karneval.","statement_en":"October 3rd celebrates the beginning of Carnival.","explanation_de":"Im Text steht: An diesem Tag feiert man die deutsche Einheit von 1990."},{"type":"choice","answer":"b","options":["a","b","c"],"statement_de":"Was rufen die Menschen beim Karneval, wenn die Wagen Süßigkeiten werfen? a) Helau! b) Kamelle! c) Alaaf!","statement_en":"What do people shout at Carnival when the floats throw sweets? a) Helau! b) Kamelle! c) Alaaf!","explanation_de":"Im Text steht: Die Menschen rufen „Kamelle!“."}]'::jsonb,
  word_count = 141,
  estimated_reading_time = 2
WHERE id = '5361acc1-da4a-4cbd-9235-a58397eba654'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Gesund leben',
  title_en = 'Living Healthily',
  content_de = 'Am 1. Januar haben viele Deutsche gute Vorsätze. Aber die meisten vergessen ihre Vorsätze schon im Februar.

Tim, 34, aus Leipzig hat es geschafft. Vor zwei Jahren hat er sich oft müde gefühlt. Sein Arzt hat ihm gesagt, dass er sich mehr bewegen muss.

Tim hat klein angefangen. Zuerst hat er sich ein einfaches Ziel gesetzt: dreimal pro Woche spazieren gehen. Nach einem Monat ist er zum ersten Mal gejoggt.

Heute läuft er zehn Kilometer ohne Pause. Er kocht jetzt fast immer selbst, weil das frische Essen gesünder ist.

Tim geht jetzt auch früher ins Bett. Er legt sein Handy eine Stunde vor dem Schlafen weg. Er sagt, dass er sich danach viel besser fühlt.

Sein Plan für nächstes Jahr steht schon fest. Er hat vor, einen Halbmarathon in Leipzig zu laufen. Sein Tipp: Ärgern Sie sich nicht über einen schlechten Tag!',
  content_en = 'On January 1st, many Germans make good resolutions. But most people forget their resolutions by February.

Tim, 34, from Leipzig has managed it. Two years ago he often felt tired. His doctor told him that he needs to exercise more.

Tim started small. First he set himself a simple goal: to go for a walk three times a week. After a month he jogged for the first time.

Today he runs ten kilometers without a break. He now almost always cooks for himself, because the fresh food is healthier.

Tim also goes to bed earlier now. He puts his phone away an hour before sleeping. He says that he feels much better afterward.

His plan for next year is already set. He plans to run a half marathon in Leipzig. His tip: don''t be annoyed about a bad day!',
  key_vocabulary = '[{"de":"der Vorsatz, ¨-e","en":"New Year''s resolution"},{"de":"müde","en":"tired"},{"de":"der Arzt, ¨-e","en":"doctor"},{"de":"sich bewegen","en":"to exercise, to move"},{"de":"das Ziel, -e","en":"goal"},{"de":"spazieren gehen","en":"to go for a walk"},{"de":"joggen","en":"to jog"},{"de":"die Pause, -n","en":"break, pause"},{"de":"gesund","en":"healthy"},{"de":"das Handy, -s","en":"mobile phone"},{"de":"der Halbmarathon, -s","en":"half marathon"},{"de":"sich ärgern (über + Akk.)","en":"to be annoyed (about)"}]'::jsonb,
  questions = '[{"question_de":"Was haben viele Deutsche am 1. Januar?","question_en":"What do many Germans have on January 1st?","answer_de":"Sie haben ihre guten Vorsätze.","answer_en":"They have their good resolutions."},{"question_de":"Was hat Tims Arzt ihm gesagt?","question_en":"What did Tim''s doctor tell him?","answer_de":"Dass er sich mehr bewegen muss.","answer_en":"That he needs to exercise more."},{"question_de":"Was war Tims erstes einfaches Ziel?","question_en":"What was Tim''s first simple goal?","answer_de":"Dreimal pro Woche spazieren zu gehen.","answer_en":"To go for a walk three times a week."},{"question_de":"Wie weit läuft Tim heute?","question_en":"How far does Tim run today?","answer_de":"Er läuft heute zehn Kilometer ohne Pause.","answer_en":"Today he runs ten kilometers without a break."},{"question_de":"Was hat Tim für nächstes Jahr vor?","question_en":"What does Tim plan for next year?","answer_de":"Er hat vor, einen Halbmarathon in Leipzig zu laufen.","answer_en":"He plans to run a half marathon in Leipzig."}]'::jsonb,
  checks = '[{"type":"rf","answer":"richtig","statement_de":"Die meisten Menschen vergessen ihre guten Vorsätze schon im Februar.","statement_en":"Most people already forget their good resolutions by February.","explanation_de":"Im Text steht: Aber die meisten vergessen ihre Vorsätze schon im Februar."},{"type":"rf","answer":"falsch","statement_de":"Tims Arzt hat gesagt, dass alles in Ordnung ist.","statement_en":"Tim''s doctor said everything was fine.","explanation_de":"Im Text steht: Sein Arzt hat ihm gesagt, dass er sich mehr bewegen muss."},{"type":"rf","answer":"falsch","statement_de":"Tims erstes Ziel war ein großer Trainingsplan.","statement_en":"Tim''s first goal was a big training plan.","explanation_de":"Im Text steht: Zuerst hat er sich ein einfaches Ziel gesetzt: dreimal pro Woche spazieren gehen."},{"type":"rf","answer":"richtig","statement_de":"Tim kocht jetzt fast immer selbst.","statement_en":"Tim now almost always cooks for himself.","explanation_de":"Im Text steht: Er kocht jetzt fast immer selbst, weil das frische Essen gesünder ist."},{"type":"rf","answer":"falsch","statement_de":"Tim geht jetzt später ins Bett als früher.","statement_en":"Tim now goes to bed later than before.","explanation_de":"Im Text steht: Tim geht jetzt auch früher ins Bett."},{"type":"choice","answer":"b","options":["a","b","c"],"statement_de":"Wie lange vor dem Schlafen legt Tim sein Handy weg? a) eine halbe Stunde b) eine Stunde c) zwei Stunden","statement_en":"How long before sleeping does Tim put his phone away? a) half an hour b) one hour c) two hours","explanation_de":"Im Text steht: Er legt sein Handy eine Stunde vor dem Schlafen weg."}]'::jsonb,
  word_count = 142,
  estimated_reading_time = 2
WHERE id = 'd287bd72-ebeb-4da6-9621-906fbc057408'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

